'use strict';
const entryRole=document.documentElement.dataset.entry;
if(entryRole){
 const staff=entryRole==='staff',user=staff?'admin':'lox',pass=staff?'admin1':'lox1';
 document.title='EcoCharge — '+(staff?'Team':'Client')+' sign-in';
 if(staff){document.querySelector('#create-demo-account')?.remove();document.querySelector('#entry-eyebrow').textContent='ECOCHARGE / TEAM OPERATIONS';document.querySelector('#entry-title').innerHTML='Your clients.<br>One clear workspace.';document.querySelector('#entry-description').textContent='Manage client balances, assigned stations and weekly plans. Review funding requests and keep every conversation in context.';document.querySelector('#entry-benefits').innerHTML='<li>Edit the client account and weekly terms</li><li>Review funding and record demo weekly allocations</li><li>Reply to client questions</li>';document.querySelector('#entry-role').textContent='TEAM ACCESS';document.querySelector('#entry-card-title').textContent='Sign in to the team demo';document.querySelector('#entry-hint').textContent='Demo login: admin · Password: admin1';document.querySelector('#entry-submit').innerHTML='Enter team workspace <span>→</span>';document.querySelector('#other-entry').href='login/';document.querySelector('#other-entry').textContent='Client? Use client sign-in →';}
 document.querySelector('#show-password').addEventListener('click',e=>{const field=document.querySelector('#entry-password');const show=field.type==='password';field.type=show?'text':'password';e.currentTarget.textContent=show?'Hide':'Show';e.currentTarget.setAttribute('aria-label',show?'Hide password':'Show password')});
 document.querySelector('#entry-form').addEventListener('submit',e=>{e.preventDefault();if(document.querySelector('#entry-username').value.trim()!==user||document.querySelector('#entry-password').value!==pass){document.querySelector('#entry-error').textContent='The username or password does not match this demo account.';return}try{sessionStorage.setItem('ecocharge-entry:'+entryRole,JSON.stringify({role:entryRole,user,at:Date.now()}));const allowed=staff?['overview','clients','requests','stations','tariffs','plan']:['dashboard','map','assets','documents','tariffs'];const next=new URL(location).searchParams.get('next');location.assign(new URL((staff?'staff/':'client/')+'?tab='+(allowed.includes(next)?next:allowed[0]),document.baseURI))}catch{document.querySelector('#entry-error').textContent='Allow browser storage to open the demo workspace.'}});
}
